const children = ($input.all()[0]?.json?.records || []);
const incidents = ($input.all()[1]?.json?.records || []);
const attendance = ($input.all()[2]?.json?.records || []);

const now = new Date();
const weekAgo = new Date(now - 7 * 24 * 60 * 60 * 1000);
const weekStr = weekAgo.toISOString().split('T')[0];

// Allergy summary
const allergies = children
  .filter(c => c.fields.allergies && c.fields.allergies !== 'None' && c.fields.allergies !== 'none')
  .map(c => `${c.fields.first_name} ${c.fields.last_name}: ${c.fields.allergies}`);

// Recent incidents
const recentIncidents = incidents.filter(i => i.fields.date >= weekStr);
const incidentTypes = {};
for (const inc of recentIncidents) {
  const t = inc.fields.incident_type || 'Other';
  incidentTypes[t] = (incidentTypes[t] || 0) + 1;
}

// Attendance stats
const recentAttendance = attendance.filter(a => a.fields.date >= weekStr);
const checkinsWithTime = recentAttendance.filter(a => a.fields.check_in);
const totalChildDays = new Set(recentAttendance.map(a => `${a.fields.child}-${a.fields.date}`)).size;

// Format
let message = `🏥 *Weekly Health Summary*\n`;
message += `Week ending: ${now.toISOString().split('T')[0]}\n\n`;

message += `*Food Allergies (${allergies.length}):*\n`;
allergies.forEach(a => message += `• ${a}\n`);
message += `\n`;

message += `*Incidents This Week:* ${recentIncidents.length}\n`;
if (recentIncidents.length > 0) {
  for (const [type, count] of Object.entries(incidentTypes)) {
    message += `• ${type}: ${count}\n`;
  }
  recentIncidents.forEach(i => {
    message += `  - ${i.fields.date}: Child #${i.fields.child} — ${i.fields.incident_type}\n`;
  });
}
message += `\n`;

message += `*Attendance:* ${totalChildDays} child-days this week`;

return [{json: {message, allergy_count: allergies.length, incident_count: recentIncidents.length, attendance_days: totalChildDays}}];

const data = $input.first().json;
const message = data.message + `\n\n💡 *Reminder:* Verify kitchen allergen substitutions are documented.`;
return [{json: {message, notify: data.incident_count > 0 || data.allergy_count > 3}}];
